package com.example.mimowidget;
import android.app.*;import android.os.*;import android.view.*;import android.webkit.*;import android.widget.*;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;
public class MainActivity extends Activity {
 WebView web; TextView status;
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+0.5f);}
 GradientDrawable buttonBackground(boolean primary){GradientDrawable d=new GradientDrawable();d.setColor(primary?Color.BLACK:Color.WHITE);d.setCornerRadius(dp(8));if(!primary)d.setStroke(dp(1),0xffe2dfdb);return d;}
 Button makeButton(String label,boolean primary){Button b=new Button(this);b.setText(label);b.setTextSize(14);b.setAllCaps(false);b.setTextColor(primary?Color.WHITE:0xff202124);b.setBackground(buttonBackground(primary));b.setElevation(0);b.setMinHeight(0);b.setMinimumHeight(0);b.setPadding(dp(18),0,dp(18),0);return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(0xfffaf9f7);getWindow().setNavigationBarColor(0xfffaf9f7);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);
 LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xfffaf9f7);root.setOnApplyWindowInsetsListener((v,insets)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);}else{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());}return insets;});
 LinearLayout header=new LinearLayout(this);header.setOrientation(1);header.setPadding(dp(16),dp(10),dp(16),dp(12));TextView title=new TextView(this);title.setText("MiMo · Token Plan");title.setTextSize(22);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);title.setTextColor(0xff202124);header.addView(title);status=new TextView(this);status.setText("Войдите в Xiaomi, откройте Token Plan и нажмите «Обновить». Затем добавьте виджет на рабочий стол.");status.setTextColor(0xff66686c);status.setTextSize(13);status.setPadding(0,dp(6),0,dp(10));header.addView(status);LinearLayout buttons=new LinearLayout(this);Button refresh=makeButton("Обновить",true);refresh.setOnClickListener(v->{CookieManager.getInstance().flush();status.setText("Загрузка данных…");new Thread(()->{String s=Data.refresh(this);runOnUiThread(()->status.setText(s));}).start();});buttons.addView(refresh,new LinearLayout.LayoutParams(-2,dp(40)));Button open=makeButton("Кабинет",false);open.setOnClickListener(v->web.loadUrl(Data.URL));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(40));lp.setMarginStart(dp(8));buttons.addView(open,lp);header.addView(buttons);root.addView(header);
 web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,true);web.setWebViewClient(new WebViewClient());web.setWebChromeClient(new WebChromeClient());root.addView(web,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);root.requestApplyInsets();web.loadUrl(Data.URL);Data.schedule(this); }
 @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}
}
